{
  "_description": "Happy path: runner POSTs a valid callback; broker enqueues and returns 204.",
  "request": {
    "method": "POST",
    "path": "/callback",
    "headers": { "Content-Type": "application/json" },
    "body": {
      "handle": "handle-abc123",
      "nonce": "nonce-xyz789",
      "result": {
        "terminal_status": "in_review",
        "pr_url": "https://github.com/example/repo/pull/42"
      }
    }
  },
  "precondition": {
    "registered": [
      {
        "handle": "handle-abc123",
        "nonce": "nonce-xyz789",
        "metadata": {
          "kind": "impl",
          "task_id": "T3",
          "feature_id": "runtime-portable-architecture",
          "started_at": "2026-01-01T00:00:00.000Z"
        }
      }
    ]
  },
  "response": {
    "status": 204
  }
}
---
{
  "_description": "Nonce mismatch: runner sends the wrong nonce for a known handle; returns 401.",
  "request": {
    "method": "POST",
    "path": "/callback",
    "headers": { "Content-Type": "application/json" },
    "body": {
      "handle": "handle-abc123",
      "nonce": "wrong-nonce",
      "result": {
        "terminal_status": "in_review"
      }
    }
  },
  "precondition": {
    "registered": [
      {
        "handle": "handle-abc123",
        "nonce": "correct-nonce",
        "metadata": {
          "kind": "impl",
          "task_id": "T3",
          "feature_id": "runtime-portable-architecture",
          "started_at": "2026-01-01T00:00:00.000Z"
        }
      }
    ]
  },
  "response": {
    "status": 401,
    "body": { "error": "nonce_mismatch" }
  }
}
---
{
  "_description": "Unknown handle: runner POSTs a handle the broker never registered; returns 401.",
  "request": {
    "method": "POST",
    "path": "/callback",
    "headers": { "Content-Type": "application/json" },
    "body": {
      "handle": "handle-unknown",
      "nonce": "nonce-any",
      "result": {
        "terminal_status": "in_review"
      }
    }
  },
  "precondition": {
    "registered": []
  },
  "response": {
    "status": 401,
    "body": { "error": "unknown_handle" }
  }
}
---
{
  "_description": "Replay attack: runner re-POSTs a handle that was already acked; returns 401.",
  "request": {
    "method": "POST",
    "path": "/callback",
    "headers": { "Content-Type": "application/json" },
    "body": {
      "handle": "handle-abc123",
      "nonce": "nonce-xyz789",
      "result": {
        "terminal_status": "in_review"
      }
    }
  },
  "precondition": {
    "registered": [],
    "_note": "Handle was registered, callback fired, and ack was called — registry entry was removed. The second POST therefore hits the unknown_handle path."
  },
  "response": {
    "status": 401,
    "body": { "error": "unknown_handle" }
  }
}
---
{
  "_description": "Blocked result: runner POSTs a blocked terminal status; broker enqueues and returns 204.",
  "request": {
    "method": "POST",
    "path": "/callback",
    "headers": { "Content-Type": "application/json" },
    "body": {
      "handle": "handle-def456",
      "nonce": "nonce-blocked",
      "result": {
        "terminal_status": "blocked",
        "blocked_reason": "missing_tool",
        "blocked_suggestion": "Install required CLI tool in the container image."
      }
    }
  },
  "precondition": {
    "registered": [
      {
        "handle": "handle-def456",
        "nonce": "nonce-blocked",
        "metadata": {
          "kind": "review-fix",
          "subkind": "rebase",
          "task_id": "T5",
          "feature_id": "runtime-portable-architecture",
          "started_at": "2026-01-01T00:00:00.000Z"
        }
      }
    ]
  },
  "response": {
    "status": 204
  }
}

