1	/**
2	 * InMemoryBrokerAdapter — CompletionBrokerPort embedded in-process adapter.
3	 *
4	 * Wave 3 (T3): reference implementation of CompletionBrokerPort using
5	 * in-process state. Designed for the local-subprocess profile where the
6	 * broker lives in the same Node process as the orchestrator.
7	 *
8	 * Responsibilities:
9	 *  - In-flight registry: Map<handle, { nonce, metadata, registered_at }>
10	 *  - Completion queue with peek-and-lock + visibility timeout
11	 *  - HTTP receiver on POST /callback (validates nonce, enqueues completion)
12	 *  - Periodic reclaim sweep returning expired-lock items to the queue
13	 *
14	 * Lifecycle:
15	 *   const broker = new InMemoryBrokerAdapter();
16	 *   const port = await broker.start();  // binds HTTP, starts reclaim timer
17	 *   // ... use broker.register / listCompleted / ack / nack ...
18	 *   await broker.stop();               // stops HTTP server and reclaim timer
19	 */
20	
21	import * as http from "node:http";
22	import * as crypto from "node:crypto";
23	import * as fs from "node:fs";
24	import * as path from "node:path";
25	import * as os from "node:os";
26	import type {
27	  CompletionBrokerPort,
28	  ExecutorHandle,
29	  HandleMetadata,
30	  ExecutorCompletion,
31	  ExecutorResult,
32	  RunnerCallbackPayload,
33	} from "@workflow/runtime-abi";
34	
35	// ── Internal types ─────────────────────────────────────────────────────────────
36	
37	interface RegistryEntry {
38	  nonce: string;
39	  metadata: HandleMetadata;
40	  registered_at: number;
41	}
42	
43	interface QueueItem {
44	  handle: ExecutorHandle;
45	  result: ExecutorResult;
46	  metadata: HandleMetadata;
47	  locked_until?: number; // unix ms; absent means unlocked
48	}
49	
50	// ── Defaults ──────────────────────────────────────────────────────────────────
51	
52	const DEFAULT_LOCK_MS = 30_000;
53	const DEFAULT_RECLAIM_INTERVAL_MS = 2_000;
54	const DEFAULT_MAX = 10;
55	
56	// ── InMemoryBrokerAdapter ─────────────────────────────────────────────────────
57	
58	export interface InMemoryBrokerAdapterOpts {
59	  /**
60	   * Port to bind the HTTP receiver on. Pass 0 (default) for OS-assigned
61	   * ephemeral port — the chosen port is written to the runtime file and
62	   * returned from start().
63	   */
64	  port?: number;
65	
66	  /** How often the reclaim sweep runs. Default: 2 000 ms. */
67	  reclaimIntervalMs?: number;
68	
69	  /**
70	   * Path to write the chosen port number after binding.
71	   * Defaults to $XDG_RUNTIME_DIR/agent-broker.port or
72	   * os.tmpdir()/agent-broker.port.
73	   */
74	  portFilePath?: string;
75	
76	  /** Clock used for timestamps (injected in tests). */
77	  clock?: { now(): number };
78	}
79	
80	export class InMemoryBrokerAdapter implements CompletionBrokerPort {
81	  private readonly _clock: { now(): number };
82	  private readonly _reclaimIntervalMs: number;
83	  private readonly _bindPort: number;
84	  private readonly _portFilePath: string;
85	
86	  private readonly registry = new Map<ExecutorHandle, RegistryEntry>();
87	  private readonly queue: QueueItem[] = [];
88	
89	  private _server: http.Server | null = null;
90	  private _port: number | null = null;
91	  private _reclaimTimer: ReturnType<typeof setInterval> | null = null;
92	
93	  constructor(opts: InMemoryBrokerAdapterOpts = {}) {
94	    this._clock = opts.clock ?? { now: () => Date.now() };
95	    this._reclaimIntervalMs = opts.reclaimIntervalMs ?? DEFAULT_RECLAIM_INTERVAL_MS;
96	    this._bindPort = opts.port ?? 0;
97	
98	    const xdgRuntimeDir = process.env["XDG_RUNTIME_DIR"] ?? os.tmpdir();
99	    this._portFilePath = opts.portFilePath ?? path.join(xdgRuntimeDir, "agent-broker.port");
100	  }
101	
102	  // ── CompletionBrokerPort ──────────────────────────────────────────────────
103	
104	  async register(
105	    handle: ExecutorHandle,
106	    nonce: string,
107	    metadata: HandleMetadata,
108	  ): Promise<void> {
109	    if (this.registry.has(handle)) {
110	      throw new Error(`InMemoryBrokerAdapter: handle already registered: ${handle}`);
111	    }
112	    this.registry.set(handle, {
113	      nonce,
114	      metadata,
115	      registered_at: this._clock.now(),
116	    });
117	  }
118	
119	  async listCompleted(opts?: {
120	    max?: number;
121	    lockMs?: number;
122	  }): Promise<ExecutorCompletion[]> {
123	    const now = this._clock.now();
124	    const max = opts?.max ?? DEFAULT_MAX;
125	    const lockMs = opts?.lockMs ?? DEFAULT_LOCK_MS;
126	
127	    this._reclaimExpired(now);
128	
129	    const results: ExecutorCompletion[] = [];
130	    for (const item of this.queue) {
131	      if (results.length >= max) break;
132	      if (item.locked_until === undefined || item.locked_until <= now) {
133	        item.locked_until = now + lockMs;
134	        results.push({
135	          handle: item.handle,
136	          result: item.result,
137	          metadata: item.metadata,
138	          locked_until: item.locked_until,
139	        });
140	      }
141	    }
142	    return results;
143	  }
144	
145	  async ack(handle: ExecutorHandle): Promise<void> {
146	    this.registry.delete(handle);
147	    const idx = this.queue.findIndex((item) => item.handle === handle);
148	    if (idx !== -1) this.queue.splice(idx, 1);
149	  }
150	
151	  async nack(handle: ExecutorHandle): Promise<void> {
152	    const item = this.queue.find((item) => item.handle === handle);
153	    if (item) {
154	      item.locked_until = undefined;
155	    }
156	  }
157	
158	  // ── HTTP server lifecycle ─────────────────────────────────────────────────
159	
160	  /**
161	   * Start the HTTP receiver.
162	   * Returns the port number the server is listening on.
163	   * Writes the port to the runtime port file for spawn code to read.
164	   */
165	  async start(): Promise<number> {
166	    if (this._server) return this._port!;
167	
168	    const server = http.createServer((req, res) => this._handleRequest(req, res));
169	
170	    await new Promise<void>((resolve, reject) => {
171	      server.listen(this._bindPort, "127.0.0.1", () => resolve());
172	      server.once("error", reject);
173	    });
174	
175	    const addr = server.address();
176	    if (!addr || typeof addr === "string") {
177	      throw new Error("InMemoryBrokerAdapter: unexpected server address");
178	    }
179	    this._port = addr.port;
180	    this._server = server;
181	
182	    // Write the port file so spawn code can read it
183	    try {
184	      fs.writeFileSync(this._portFilePath, String(this._port), "utf8");
185	    } catch {
186	      // Non-fatal — spawn code can also call getPort()
187	    }
188	
189	    // Start reclaim sweep
190	    this._reclaimTimer = setInterval(
191	      () => this._reclaimExpired(this._clock.now()),
192	      this._reclaimIntervalMs,
193	    );
194	    // Prevent the timer from keeping the process alive
195	    if (this._reclaimTimer.unref) {
196	      this._reclaimTimer.unref();
197	    }
198	
199	    return this._port;
200	  }
201	
202	  /**
203	   * Stop the HTTP receiver and reclaim timer.
204	   * Safe to call multiple times.
205	   */
206	  async stop(): Promise<void> {
207	    if (this._reclaimTimer) {
208	      clearInterval(this._reclaimTimer);
209	      this._reclaimTimer = null;
210	    }
211	
212	    if (this._server) {
213	      await new Promise<void>((resolve, reject) => {
214	        this._server!.close((err) => (err ? reject(err) : resolve()));
215	      });
216	      this._server = null;
217	      this._port = null;
218	    }
219	
220	    // Remove the port file
221	    try {
222	      fs.unlinkSync(this._portFilePath);
223	    } catch {
224	      // OK — file may not exist
225	    }
226	  }
227	
228	  /**
229	   * The port number the HTTP receiver is listening on.
230	   * Null before start() is called.
231	   */
232	  getPort(): number | null {
233	    return this._port;
234	  }
235	
236	  /**
237	   * The full callback URL that runners should POST to.
238	   * Null before start() is called.
239	   */
240	  getCallbackUrl(): string | null {
241	    return this._port !== null
242	      ? `http://127.0.0.1:${this._port}/callback`
243	      : null;
244	  }
245	
246	  // ── Internal ──────────────────────────────────────────────────────────────
247	
248	  private _handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
249	    if (req.method !== "POST" || req.url !== "/callback") {
250	      res.writeHead(404);
251	      res.end(JSON.stringify({ error: "not_found" }));
252	      return;
253	    }
254	
255	    const chunks: Buffer[] = [];
256	    req.on("data", (chunk: Buffer) => chunks.push(chunk));
257	    req.on("end", () => {
258	      let payload: RunnerCallbackPayload;
259	      try {
260	        payload = JSON.parse(Buffer.concat(chunks).toString("utf8"));
261	      } catch {
262	        res.writeHead(400, { "Content-Type": "application/json" });
263	        res.end(JSON.stringify({ error: "invalid_json" }));
264	        return;
265	      }
266	
267	      const outcome = this._processCallback(payload);
268	      res.writeHead(outcome.status, { "Content-Type": "application/json" });
269	      res.end(JSON.stringify(outcome.body));
270	    });
271	  }
272	
273	  private _processCallback(
274	    payload: RunnerCallbackPayload,
275	  ): { status: number; body: unknown } {
276	    const { handle, nonce, result } = payload;
277	
278	    const entry = this.registry.get(handle);
279	    if (!entry) {
280	      return { status: 401, body: { error: "unknown_handle" } };
281	    }
282	
283	    const expectedBuf = Buffer.from(entry.nonce);
284	    const actualBuf = Buffer.from(nonce);
285	    const nonceValid =
286	      expectedBuf.length === actualBuf.length &&
287	      crypto.timingSafeEqual(expectedBuf, actualBuf);
288	    if (!nonceValid) {
289	      return { status: 401, body: { error: "nonce_mismatch" } };
290	    }
291	
292	    this.queue.push({
293	      handle,
294	      result,
295	      metadata: entry.metadata,
296	    });
297	
298	    return { status: 204, body: {} };
299	  }
300	
301	  private _reclaimExpired(now: number): void {
302	    for (const item of this.queue) {
303	      if (item.locked_until !== undefined && item.locked_until <= now) {
304	        item.locked_until = undefined;
305	      }
306	    }
307	  }
308	
309	  // ── Diagnostic helpers (tests + T7 conformance) ───────────────────────────
310	
311	  /** Number of handles currently in the in-flight registry. */
312	  registrySize(): number {
313	    return this.registry.size;
314	  }
315	
316	  /** Total items in the completion queue (locked or unlocked). */
317	  queueDepth(): number {
318	    return this.queue.length;
319	  }
320	
321	  /** Items currently locked (visibility timeout not yet expired). */
322	  lockedCount(): number {
323	    const now = this._clock.now();
324	    return this.queue.filter(
325	      (item) => item.locked_until !== undefined && item.locked_until > now,
326	    ).length;
327	  }
328	
329	  /** Unique nonce string (helper for adapters that call register). */
330	  static generateNonce(): string {
331	    return crypto.randomBytes(32).toString("hex");
332	  }
333	}
