/**
 * InMemoryBrokerAdapter — CompletionBrokerPort embedded in-process adapter.
 *
 * Wave 3 (T3): reference implementation of CompletionBrokerPort using
 * in-process state. Designed for the local-subprocess profile where the
 * broker lives in the same Node process as the orchestrator.
 *
 * Responsibilities:
 *  - In-flight registry: Map<handle, { nonce, metadata, registered_at }>
 *  - Completion queue with peek-and-lock + visibility timeout
 *  - HTTP receiver on POST /callback (validates nonce, enqueues completion)
 *  - Periodic reclaim sweep returning expired-lock items to the queue
 *
 * Lifecycle:
 *   const broker = new InMemoryBrokerAdapter();
 *   const port = await broker.start();  // binds HTTP, starts reclaim timer
 *   // ... use broker.register / listCompleted / ack / nack ...
 *   await broker.stop();               // stops HTTP server and reclaim timer
 */

import * as http from "node:http";
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import type {
  CompletionBrokerPort,
  ExecutorHandle,
  HandleMetadata,
  ExecutorCompletion,
  ExecutorResult,
  RunnerCallbackPayload,
} from "@workflow/runtime-abi";

// ── Internal types ─────────────────────────────────────────────────────────────

interface RegistryEntry {
  nonce: string;
  metadata: HandleMetadata;
  registered_at: number;
}

interface QueueItem {
  handle: ExecutorHandle;
  result: ExecutorResult;
  metadata: HandleMetadata;
  locked_until?: number; // unix ms; absent means unlocked
}

// ── Defaults ──────────────────────────────────────────────────────────────────

const DEFAULT_LOCK_MS = 30_000;
const DEFAULT_RECLAIM_INTERVAL_MS = 2_000;
const DEFAULT_MAX = 10;

// ── InMemoryBrokerAdapter ─────────────────────────────────────────────────────

export interface InMemoryBrokerAdapterOpts {
  /**
   * Port to bind the HTTP receiver on. Pass 0 (default) for OS-assigned
   * ephemeral port — the chosen port is written to the runtime file and
   * returned from start().
   */
  port?: number;

  /** How often the reclaim sweep runs. Default: 2 000 ms. */
  reclaimIntervalMs?: number;

  /**
   * Path to write the chosen port number after binding.
   * Defaults to $XDG_RUNTIME_DIR/agent-broker.port or
   * os.tmpdir()/agent-broker.port.
   */
  portFilePath?: string;

  /** Clock used for timestamps (injected in tests). */
  clock?: { now(): number };
}

export class InMemoryBrokerAdapter implements CompletionBrokerPort {
  private readonly _clock: { now(): number };
  private readonly _reclaimIntervalMs: number;
  private readonly _bindPort: number;
  private readonly _portFilePath: string;

  private readonly registry = new Map<ExecutorHandle, RegistryEntry>();
  private readonly queue: QueueItem[] = [];

  private _server: http.Server | null = null;
  private _port: number | null = null;
  private _reclaimTimer: ReturnType<typeof setInterval> | null = null;

  constructor(opts: InMemoryBrokerAdapterOpts = {}) {
    this._clock = opts.clock ?? { now: () => Date.now() };
    this._reclaimIntervalMs = opts.reclaimIntervalMs ?? DEFAULT_RECLAIM_INTERVAL_MS;
    this._bindPort = opts.port ?? 0;

    const xdgRuntimeDir = process.env["XDG_RUNTIME_DIR"] ?? os.tmpdir();
    this._portFilePath = opts.portFilePath ?? path.join(xdgRuntimeDir, "agent-broker.port");
  }

  // ── CompletionBrokerPort ──────────────────────────────────────────────────

  async register(
    handle: ExecutorHandle,
    nonce: string,
    metadata: HandleMetadata,
  ): Promise<void> {
    if (this.registry.has(handle)) {
      throw new Error(`InMemoryBrokerAdapter: handle already registered: ${handle}`);
    }
    this.registry.set(handle, {
      nonce,
      metadata,
      registered_at: this._clock.now(),
    });
  }

  async listCompleted(opts?: {
    max?: number;
    lockMs?: number;
  }): Promise<ExecutorCompletion[]> {
    const now = this._clock.now();
    const max = opts?.max ?? DEFAULT_MAX;
    const lockMs = opts?.lockMs ?? DEFAULT_LOCK_MS;

    this._reclaimExpired(now);

    const results: ExecutorCompletion[] = [];
    for (const item of this.queue) {
      if (results.length >= max) break;
      if (item.locked_until === undefined || item.locked_until <= now) {
        item.locked_until = now + lockMs;
        results.push({
          handle: item.handle,
          result: item.result,
          metadata: item.metadata,
          locked_until: item.locked_until,
        });
      }
    }
    return results;
  }

  async ack(handle: ExecutorHandle): Promise<void> {
    this.registry.delete(handle);
    const idx = this.queue.findIndex((item) => item.handle === handle);
    if (idx !== -1) this.queue.splice(idx, 1);
  }

  async nack(handle: ExecutorHandle): Promise<void> {
    const item = this.queue.find((item) => item.handle === handle);
    if (item) {
      item.locked_until = undefined;
    }
  }

  // ── HTTP server lifecycle ─────────────────────────────────────────────────

  /**
   * Start the HTTP receiver.
   * Returns the port number the server is listening on.
   * Writes the port to the runtime port file for spawn code to read.
   */
  async start(): Promise<number> {
    if (this._server) return this._port!;

    const server = http.createServer((req, res) => this._handleRequest(req, res));

    await new Promise<void>((resolve, reject) => {
      server.listen(this._bindPort, "127.0.0.1", () => resolve());
      server.once("error", reject);
    });

    const addr = server.address();
    if (!addr || typeof addr === "string") {
      throw new Error("InMemoryBrokerAdapter: unexpected server address");
    }
    this._port = addr.port;
    this._server = server;

    // Write the port file so spawn code can read it
    try {
      fs.writeFileSync(this._portFilePath, String(this._port), "utf8");
    } catch {
      // Non-fatal — spawn code can also call getPort()
    }

    // Start reclaim sweep
    this._reclaimTimer = setInterval(
      () => this._reclaimExpired(this._clock.now()),
      this._reclaimIntervalMs,
    );
    // Prevent the timer from keeping the process alive
    if (this._reclaimTimer.unref) {
      this._reclaimTimer.unref();
    }

    return this._port;
  }

  /**
   * Stop the HTTP receiver and reclaim timer.
   * Safe to call multiple times.
   */
  async stop(): Promise<void> {
    if (this._reclaimTimer) {
      clearInterval(this._reclaimTimer);
      this._reclaimTimer = null;
    }

    if (this._server) {
      await new Promise<void>((resolve, reject) => {
        this._server!.close((err) => (err ? reject(err) : resolve()));
      });
      this._server = null;
      this._port = null;
    }

    // Remove the port file
    try {
      fs.unlinkSync(this._portFilePath);
    } catch {
      // OK — file may not exist
    }
  }

  /**
   * The port number the HTTP receiver is listening on.
   * Null before start() is called.
   */
  getPort(): number | null {
    return this._port;
  }

  /**
   * The full callback URL that runners should POST to.
   * Null before start() is called.
   */
  getCallbackUrl(): string | null {
    return this._port !== null
      ? `http://127.0.0.1:${this._port}/callback`
      : null;
  }

  // ── Internal ──────────────────────────────────────────────────────────────

  private _handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
    if (req.method !== "POST" || req.url !== "/callback") {
      res.writeHead(404);
      res.end(JSON.stringify({ error: "not_found" }));
      return;
    }

    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      let payload: RunnerCallbackPayload;
      try {
        payload = JSON.parse(Buffer.concat(chunks).toString("utf8"));
      } catch {
        res.writeHead(400, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "invalid_json" }));
        return;
      }

      const outcome = this._processCallback(payload);
      res.writeHead(outcome.status, { "Content-Type": "application/json" });
      res.end(JSON.stringify(outcome.body));
    });
  }

  private _processCallback(
    payload: RunnerCallbackPayload,
  ): { status: number; body: unknown } {
    const { handle, nonce, result } = payload;

    const entry = this.registry.get(handle);
    if (!entry) {
      return { status: 401, body: { error: "unknown_handle" } };
    }

    const expectedBuf = Buffer.from(entry.nonce);
    const actualBuf = Buffer.from(nonce);
    const nonceValid =
      expectedBuf.length === actualBuf.length &&
      crypto.timingSafeEqual(expectedBuf, actualBuf);
    if (!nonceValid) {
      return { status: 401, body: { error: "nonce_mismatch" } };
    }

    this.queue.push({
      handle,
      result,
      metadata: entry.metadata,
    });

    return { status: 204, body: {} };
  }

  private _reclaimExpired(now: number): void {
    for (const item of this.queue) {
      if (item.locked_until !== undefined && item.locked_until <= now) {
        item.locked_until = undefined;
      }
    }
  }

  // ── Diagnostic helpers (tests + T7 conformance) ───────────────────────────

  /** Number of handles currently in the in-flight registry. */
  registrySize(): number {
    return this.registry.size;
  }

  /** Total items in the completion queue (locked or unlocked). */
  queueDepth(): number {
    return this.queue.length;
  }

  /** Items currently locked (visibility timeout not yet expired). */
  lockedCount(): number {
    const now = this._clock.now();
    return this.queue.filter(
      (item) => item.locked_until !== undefined && item.locked_until > now,
    ).length;
  }

  /** Unique nonce string (helper for adapters that call register). */
  static generateNonce(): string {
    return crypto.randomBytes(32).toString("hex");
  }
}

