/**
 * ABI contract between the orchestrator and any executor.
 *
 * The orchestrator serialises ExecutorInput into env vars before spawning
 * the executor process. The executor writes an ExecutorResult to the path
 * at resultPath. The orchestrator reads and validates that file on exit.
 */

// ── Handle / completion types (Wave 1 — ports-and-adapters foundation) ───────

/** Opaque identifier for a single in-flight executor run. */
export type ExecutorHandle = string;

/** Discriminates claim work from review-fix work in the reap loop. */
export type HandleKind = "impl" | "review-fix";

/** Sub-discriminator for review-fix handles. */
export type HandleSubkind = "rebase" | "respond";

/**
 * Metadata registered with the broker at submit time.
 * Carried on every completion so any orchestrator can dispatch without
 * needing prior knowledge of the submit — opportunistic dispatch.
 */
export interface HandleMetadata {
  kind: HandleKind;
  subkind?: HandleSubkind;
  task_id: string;
  feature_id: string;
  tenant_id?: string;
  started_at: string; // ISO 8601
}

/**
 * One item returned by CompletionBrokerPort.listCompleted (peek-and-lock).
 * locked_until is present when the broker has marked the item locked.
 */
export interface ExecutorCompletion {
  handle: ExecutorHandle;
  result: ExecutorResult;
  metadata: HandleMetadata;
  locked_until?: number; // unix ms timestamp
}

/**
 * Extended input for ExecutorPort.submit.
 * Adds the callback URL and per-handle nonce that the runner wrapper uses
 * to POST its result back to the completion broker.
 */
export interface ExecutorPortInput extends ExecutorInput {
  /** The URL the runner wrapper will POST { handle, nonce, result } to. */
  callbackUrl: string;
  /** Single-use token; validated by the broker on POST; invalidated on ack. */
  nonce: string;
}

/** HTTP POST body the runner wrapper sends to the broker on completion. */
export interface RunnerCallbackPayload {
  handle: ExecutorHandle;
  nonce: string;
  result: ExecutorResult;
}

// ── Original ABI types (kept for backward compatibility) ─────────────────────

export interface ExecutorInput {
  taskId: string;
  featureId: string;
  workspaceId: string;
  /** Git URL of the implementation repo (SSH or HTTPS). */
  taskRepoUrl: string;
  /** Feature branch the executor must check out and push to. */
  taskRepoBranch: string;
  /**
   * Working-directory path. The **executor** materializes the repo here:
   * if the path already exists with `origin` matching `taskRepoUrl`,
   * fetch + checkout + pull; otherwise clone fresh from `taskRepoUrl`.
   * The orchestrator may pre-populate this path as an optimization in
   * shared-filesystem topologies, but it is not required to.
   */
  taskRepoPath: string;
  /** Path to the markdown briefing file written by the orchestrator. */
  briefingPath: string;
  /** Path the executor must write result.json to. */
  resultPath: string;
  /** Optional token budget; absent for non-LLM executors. */
  budgetTokens?: number;
  sshPrivateKey: string;
  githubToken: string;
}

export type TerminalStatus = "in_review" | "blocked" | "failed";

export interface ExecutorResult {
  terminal_status: TerminalStatus;
  token_usage?: { input: number; output: number };
  /** Required when terminal_status === "blocked". */
  blocked_reason?: string;
  /** Required when terminal_status === "blocked". */
  blocked_suggestion?: string;
  /**
   * URL of the implementation-repo pull request opened by the executor.
   * Populated whenever the executor opened a PR — independent of terminal_status.
   * A blocked task with a draft PR still reports pr_url so the failed attempt is
   * documented. Absent when no commits were pushed (no PR to open).
   */
  pr_url?: string;
  /**
   * Path to a handover.md file written by the executor or the post-hoc recovery
   * routine (Layer 1). Optional — present only when a handover exists.
   * The orchestrator reads this on re-claim and prepends its contents to the next
   * agent's briefing under a "## Continuing previous run" heading (Layer 3).
   */
  handover_path?: string;
}

/**
 * The orchestrator-side seam every executor must satisfy.
 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
 */
export interface ExecutorAdapter {
  run(input: ExecutorInput): Promise<ExecutorResult>;
}

/**
 * Port interfaces for the hexagonal / ports-and-adapters architecture.
 *
 * Each port is a TypeScript interface the orchestrator core depends on.
 * Concrete adapter implementations are injected at startup based on a
 * named profile (e.g. `local-subprocess`, `local-docker`).
 *
 * Wave 1: interfaces + fake adapters only; real adapters land in Wave 2.
 */

import type {
  ExecutorHandle,
  ExecutorPortInput,
  ExecutorResult,
  HandleMetadata,
  ExecutorCompletion,
} from "./types.js";

// ── ExecutorPort ──────────────────────────────────────────────────────────────

/**
 * Spawn an executor and return immediately.
 *
 * submit() registers the handle with the broker, spawns the runner wrapper,
 * and returns the handle — it does NOT wait for the executor to finish.
 * Completion is delivered via CompletionBrokerPort (runner callback → broker
 * enqueue → orchestrator listCompleted + ack).
 *
 * readResult() is a no-op for local profiles where the result rides in the
 * callback payload; it exists for adapters that only store a pointer (e.g.
 * an S3 key) rather than the full result in the broker.
 */
export interface ExecutorPort {
  /** Spawn the executor; return a handle immediately. */
  submit(input: ExecutorPortInput): Promise<ExecutorHandle>;
  /** Retrieve the full result when the broker only stored a pointer. */
  readResult(handle: ExecutorHandle): Promise<ExecutorResult>;
}

// ── CompletionBrokerPort ──────────────────────────────────────────────────────

/**
 * Shared completion broker — in-flight handle registry + completion queue.
 *
 * The broker is the single rendezvous point between runners and orchestrators:
 * - runners POST { handle, nonce, result } to the broker's HTTP receiver
 * - orchestrators drain completions via listCompleted (peek-and-lock)
 *
 * Any orchestrator can drain any completion — dispatch is opportunistic,
 * not pinned to the orchestrator that submitted.
 *
 * Adapters:
 *   InMemoryBrokerAdapter — embedded in the orchestrator for local-subprocess.
 *   RedisBrokerAdapter    — separate broker service for local-docker.
 */
export interface CompletionBrokerPort {
  /**
   * Register a handle as in-flight before submit.
   * The broker stores the nonce and metadata for callback validation
   * and routing. Must be called before ExecutorPort.submit.
   */
  register(
    handle: ExecutorHandle,
    nonce: string,
    metadata: HandleMetadata,
  ): Promise<void>;

  /**
   * Peek and lock up to N completions atomically.
   * Returned items are locked for lockMs; a locked item that is not acked
   * within lockMs is returned to the queue by the broker's reclaim sweep.
   */
  listCompleted(opts?: {
    max?: number;
    lockMs?: number;
  }): Promise<ExecutorCompletion[]>;

  /**
   * Commit the consumption of a completion.
   * Invalidates the nonce; removes the handle from the in-flight registry.
   */
  ack(handle: ExecutorHandle): Promise<void>;

  /**
   * Return a locked completion to the queue immediately.
   * Used during graceful shutdown before the orchestrator could dispatch.
   */
  nack(handle: ExecutorHandle): Promise<void>;
}

// ── BriefingTransportPort ─────────────────────────────────────────────────────

/**
 * Deliver a briefing document to an executor.
 *
 * The adapter writes the briefing content somewhere the executor can read it
 * and returns the path (or URL) to pass via env vars at spawn time.
 *
 * Adapters:
 *   LocalFileBriefingAdapter — writes to a shared host path (local-subprocess).
 *   ConfigMapBriefingAdapter — writes a K8s ConfigMap (future).
 *   S3SignedUrlBriefingAdapter — uploads to S3, returns a pre-signed URL (future).
 */
export interface BriefingTransportPort {
  /**
   * Write briefing content for the given handle.
   * Returns the path or URL the executor should read from.
   */
  put(handle: ExecutorHandle, content: string): Promise<string>;

  /** Remove the briefing after the handle is acked. */
  cleanup(handle: ExecutorHandle): Promise<void>;
}

// ── WorkflowStatePort ─────────────────────────────────────────────────────────

/**
 * Read/write workflow state (task YAMLs, logs).
 *
 * Git remains authoritative for workflow state in every profile.
 * The adapter clones each workspace repo, reads/writes task YAMLs,
 * commits and pushes.
 *
 * Adapters:
 *   GitWorkflowStateAdapter — clone + commit + push (all profiles).
 *   DBWorkflowStateAdapter  — Postgres (future high-throughput profile).
 */
export interface WorkflowStatePort {
  /** Read the parsed task YAML for the given task. */
  readTask(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
  ): Promise<Record<string, unknown>>;

  /** Write the task YAML. */
  writeTask(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    data: Record<string, unknown>,
  ): Promise<void>;

  /** Append a log entry to the task YAML. */
  appendLog(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    entry: Record<string, unknown>,
  ): Promise<void>;

  /**
   * Persist the handle on the task YAML at submit time.
   * Enables crash-recovery reconciliation — a lost broker can be
   * reconciled by scanning in-progress task YAMLs for their handles.
   */
  persistHandle(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    handle: ExecutorHandle,
  ): Promise<void>;
}

// ── CredentialPort ────────────────────────────────────────────────────────────

/**
 * Provide credentials to executor processes at spawn time.
 *
 * In this feature the value is always a single tenant; the tenantId
 * parameter is plumbed now so the call-site shape is ready for the
 * future multi-tenant feature without modifying every call site.
 *
 * Adapters:
 *   EnvCredentialAdapter          — reads from process.env (all local profiles).
 *   GitHubAppCredentialAdapter    — mints short-lived GitHub App tokens (future).
 */
export interface CredentialPort {
  /** Return a GitHub access token for the given tenant. */
  getGitHubToken(tenantId?: string): Promise<string>;

  /** Return the raw SSH private key PEM content for the given tenant. */
  getSshPrivateKey(tenantId?: string): Promise<string>;
}

// ── WorkspacePullPort ─────────────────────────────────────────────────────────

/**
 * Materialize a workspace (management) repo for the orchestrator's use.
 *
 * The orchestrator reads workspace.yaml and task YAMLs from a local clone.
 * This port encapsulates the clone + pull operation.
 *
 * Adapters:
 *   GitClonePullAdapter — git clone / fetch + checkout + pull.
 */
export interface WorkspacePullPort {
  /** Ensure the repo at repoUrl is materialized at targetPath on branch. */
  pull(
    repoUrl: string,
    targetPath: string,
    branch: string,
    sshKeyPath?: string,
  ): Promise<void>;
}

// ── EventEmitterPort ──────────────────────────────────────────────────────────

/**
 * Emit structured events and metrics.
 *
 * The orchestrator core emits domain events (task_claimed, executor_spawn,
 * executor_result, etc.) through this port. Adapters decide how to surface
 * them (stdout JSON, OpenTelemetry, etc.).
 *
 * Adapters:
 *   StdoutJsonEmitter — JSON lines to stdout (all local profiles).
 */
export interface EventEmitterPort {
  /** Emit an event with an optional data payload. */
  emit(event: string, data?: Record<string, unknown>): void;
}

// ── SchedulerPort ─────────────────────────────────────────────────────────────

/**
 * Control the orchestrator's cycle cadence.
 *
 * The orchestrator sleeps between cycles; this port wraps that sleep
 * so tests can advance time without wall-clock waits.
 *
 * Adapters:
 *   SimpleSleepScheduler — setTimeout-based sleep.
 */
export interface SchedulerPort {
  /** Sleep for the given number of milliseconds. */
  sleep(ms: number): Promise<void>;
}

// ── ClockPort ─────────────────────────────────────────────────────────────────

/**
 * Abstraction over time, for deterministic testing of time-sensitive logic
 * (visibility timeouts, lease expiry, deadline checks).
 *
 * Adapters:
 *   RealClock — delegates to Date.now() and setTimeout.
 */
export interface ClockPort {
  /** Current time as unix milliseconds. */
  now(): number;

  /** Current time as an ISO 8601 string. */
  nowIso(): string;

  /** Sleep for the given number of milliseconds. */
  sleep(ms: number): Promise<void>;
}

