package store

import (
	"context"
	"crypto/subtle"
	"sync"
	"time"
)

// MemoryStore is an in-process Store implementation used for testing.
type MemoryStore struct {
	mu       sync.Mutex
	registry map[string]memRegistryEntry
	queue    []memQueueItem
	clock    func() int64
}

type memRegistryEntry struct {
	nonce    string
	metadata HandleMetadata
}

type memQueueItem struct {
	handle      string
	result      ExecutorResult
	metadata    HandleMetadata
	lockedUntil int64 // 0 = unlocked; >0 = unix ms lock expiry
}

// NewMemoryStore returns a MemoryStore backed by the real wall clock.
func NewMemoryStore() *MemoryStore {
	return &MemoryStore{
		registry: make(map[string]memRegistryEntry),
		clock:    func() int64 { return time.Now().UnixMilli() },
	}
}

// NewMemoryStoreWithClock returns a MemoryStore with an injected clock (for tests).
func NewMemoryStoreWithClock(clock func() int64) *MemoryStore {
	return &MemoryStore{
		registry: make(map[string]memRegistryEntry),
		clock:    clock,
	}
}

func (s *MemoryStore) Register(_ context.Context, handle, nonce string, metadata HandleMetadata) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.registry[handle]; ok {
		return ErrAlreadyRegistered
	}
	s.registry[handle] = memRegistryEntry{nonce: nonce, metadata: metadata}
	return nil
}

func (s *MemoryStore) ValidateCallback(_ context.Context, handle, nonce string, result ExecutorResult) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	entry, ok := s.registry[handle]
	if !ok {
		return ErrUnknownHandle
	}
	if subtle.ConstantTimeCompare([]byte(nonce), []byte(entry.nonce)) == 0 {
		return ErrNonceMismatch
	}

	s.queue = append(s.queue, memQueueItem{
		handle:   handle,
		result:   result,
		metadata: entry.metadata,
	})
	return nil
}

func (s *MemoryStore) ListCompleted(_ context.Context, max int, lockMs int64) ([]Completion, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := s.clock()
	lockUntil := now + lockMs

	var results []Completion
	for i := range s.queue {
		if len(results) >= max {
			break
		}
		item := &s.queue[i]
		if item.lockedUntil == 0 || item.lockedUntil <= now {
			item.lockedUntil = lockUntil
			lu := lockUntil
			results = append(results, Completion{
				Handle:      item.handle,
				Result:      item.result,
				Metadata:    item.metadata,
				LockedUntil: &lu,
			})
		}
	}
	return results, nil
}

func (s *MemoryStore) Ack(_ context.Context, handle string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	delete(s.registry, handle)
	for i, item := range s.queue {
		if item.handle == handle {
			s.queue = append(s.queue[:i], s.queue[i+1:]...)
			return nil
		}
	}
	return nil
}

func (s *MemoryStore) Nack(_ context.Context, handle string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	for i := range s.queue {
		if s.queue[i].handle == handle {
			s.queue[i].lockedUntil = 0
			return nil
		}
	}
	return nil
}

func (s *MemoryStore) ReclaimExpired(_ context.Context) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := s.clock()
	for i := range s.queue {
		if s.queue[i].lockedUntil > 0 && s.queue[i].lockedUntil <= now {
			s.queue[i].lockedUntil = 0
		}
	}
	return nil
}

// RegistrySize returns the number of handles in the in-flight registry (diagnostic helper).
func (s *MemoryStore) RegistrySize() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.registry)
}

// QueueDepth returns the total number of items in the completion queue (diagnostic helper).
func (s *MemoryStore) QueueDepth() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.queue)
}

