	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/tiendv89/agent-workflow/runtime/broker/internal/server"
	"github.com/tiendv89/agent-workflow/runtime/broker/internal/store"
)

// ── helpers ───────────────────────────────────────────────────────────────────

func newServer() *server.Server {
	return server.New(store.NewMemoryStore())
}

func newServerWithStore(st store.Store) *server.Server {
	return server.New(st)
}

func post(srv http.Handler, path string, body any) *httptest.ResponseRecorder {
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			panic(err)
		}
	}
	req := httptest.NewRequest(http.MethodPost, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	return rr
}

func getBody(t *testing.T, rr *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var out map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&out); err != nil {
		t.Fatalf("decode body: %v", err)
	}
	return out
}

func mustRegister(t *testing.T, srv http.Handler, handle, nonce string, meta store.HandleMetadata) {
	t.Helper()
	rr := post(srv, "/register", map[string]any{
		"handle":   handle,
		"nonce":    nonce,
		"metadata": meta,
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("register failed: %d %s", rr.Code, rr.Body.String())
	}
}

func mustCallback(t *testing.T, srv http.Handler, handle, nonce string, result store.ExecutorResult) {
	t.Helper()
	rr := post(srv, "/callback", map[string]any{
		"handle": handle,
		"nonce":  nonce,
		"result": result,
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("callback failed: %d %s", rr.Code, rr.Body.String())
	}
}

func testMeta(taskID string) store.HandleMetadata {
	return store.HandleMetadata{
		Kind:      "impl",
		TaskID:    taskID,
		FeatureID: "test-feature",
		StartedAt: "2026-01-01T00:00:00.000Z",
	}
}

// ── protocol fixture conformance tests ───────────────────────────────────────
// These tests replay the JSON fixtures in runtime/broker-protocol/fixtures/
// and assert identical behaviour to InMemoryBrokerAdapter (TypeScript, T3).

func TestFixture_CallbackValid(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "handle-abc123", "nonce-xyz789", store.HandleMetadata{
		Kind:      "impl",
		TaskID:    "T3",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-abc123",
		"nonce":  "nonce-xyz789",
		"result": map[string]any{
			"terminal_status": "in_review",
			"pr_url":          "https://github.com/example/repo/pull/42",
		},
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d: %s", rr.Code, rr.Body.String())
	}
}

func TestFixture_CallbackUnknownHandle(t *testing.T) {
	srv := newServer()
	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-unknown",
		"nonce":  "nonce-any",
		"result": map[string]any{"terminal_status": "in_review"},
	})
	if rr.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401, got %d", rr.Code)
	}
	body := getBody(t, rr)
	if body["error"] != "unknown_handle" {
		t.Fatalf("expected error=unknown_handle, got %v", body["error"])
	}
}

func TestFixture_CallbackNonceMismatch(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "handle-abc123", "correct-nonce", store.HandleMetadata{
		Kind:      "impl",
		TaskID:    "T3",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-abc123",
		"nonce":  "wrong-nonce",
		"result": map[string]any{"terminal_status": "in_review"},
	})
	if rr.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401, got %d", rr.Code)
	}
	body := getBody(t, rr)
	if body["error"] != "nonce_mismatch" {
		t.Fatalf("expected error=nonce_mismatch, got %v", body["error"])
	}
}

func TestFixture_CallbackReplay(t *testing.T) {
	srv := newServer()
	// Register → callback → list → ack (removes registry) → replay.
	mustRegister(t, srv, "handle-abc123", "nonce-xyz789", testMeta("T3"))
	mustCallback(t, srv, "handle-abc123", "nonce-xyz789", store.ExecutorResult{TerminalStatus: "in_review"})

	// Ack the handle (removes from registry — replay should now return unknown_handle).
	post(srv, "/list-completed", map[string]any{"max": 1})
	post(srv, "/ack", map[string]any{"handle": "handle-abc123"})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-abc123",
		"nonce":  "nonce-xyz789",
		"result": map[string]any{"terminal_status": "in_review"},
	})
	if rr.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 on replay, got %d", rr.Code)
	}
	body := getBody(t, rr)
	if body["error"] != "unknown_handle" {
		t.Fatalf("expected error=unknown_handle, got %v", body["error"])
	}
}

func TestFixture_CallbackBlockedResult(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "handle-def456", "nonce-blocked", store.HandleMetadata{
		Kind:      "review-fix",
		Subkind:   "rebase",
		TaskID:    "T5",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-def456",
		"nonce":  "nonce-blocked",
		"result": map[string]any{
			"terminal_status":    "blocked",
			"blocked_reason":     "missing_tool",
			"blocked_suggestion": "Install required CLI tool in the container image.",
		},
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d: %s", rr.Code, rr.Body.String())
	}
}

// ── callback route tests ──────────────────────────────────────────────────────

func TestCallback_MalformedJSON(t *testing.T) {
	srv := newServer()
	req := httptest.NewRequest(http.MethodPost, "/callback", bytes.NewBufferString("not-json"))
	req.Header.Set("Content-Type", "application/json")
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d", rr.Code)
	}
}

func TestCallback_UnknownRoute(t *testing.T) {
	srv := newServer()
	req := httptest.NewRequest(http.MethodGet, "/unknown", nil)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusNotFound {
		t.Fatalf("expected 404, got %d", rr.Code)
	}
}

// ── register tests ────────────────────────────────────────────────────────────

func TestRegister_DuplicateHandle(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "h1", "n1", testMeta("T1"))

	rr := post(srv, "/register", map[string]any{
		"handle":   "h1",
		"nonce":    "n2",
		"metadata": testMeta("T1"),
	})
	if rr.Code != http.StatusConflict {
		t.Fatalf("expected 409 on duplicate, got %d", rr.Code)
	}
}

// ── list-completed tests ──────────────────────────────────────────────────────

func TestListCompleted_EmptyQueue(t *testing.T) {
	srv := newServer()
	rr := post(srv, "/list-completed", map[string]any{"max": 5})
	if rr.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rr.Code)
	}
	var items []any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 0 {
		t.Fatalf("expected empty list, got %d items", len(items))
	}
}

func TestListCompleted_ReturnsEnqueuedCompletion(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	rr := post(srv, "/list-completed", map[string]any{"max": 5})
	if rr.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rr.Code)
	}
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}
	if items[0]["handle"] != "h1" {
		t.Fatalf("expected handle=h1, got %v", items[0]["handle"])
	}
}

func TestListCompleted_LockedItemNotReturnedAgain(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	// First call locks the item.
	post(srv, "/list-completed", map[string]any{"max": 5, "lock_ms": 60000})
	// Second call should return nothing.
	rr := post(srv, "/list-completed", map[string]any{"max": 5, "lock_ms": 60000})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 0 {
		t.Fatalf("expected 0 items (still locked), got %d", len(items))
	}
}

func TestListCompleted_RespectsMaxOption(t *testing.T) {
	srv := newServer()
	for i := 0; i < 5; i++ {
		h := "h" + string(rune('0'+i))
		n := "n" + string(rune('0'+i))
		mustRegister(t, srv, h, n, testMeta("T"+string(rune('0'+i))))
		mustCallback(t, srv, h, n, store.ExecutorResult{TerminalStatus: "in_review"})
	}

	rr := post(srv, "/list-completed", map[string]any{"max": 2})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 2 {
		t.Fatalf("expected 2 items (max=2), got %d", len(items))
	}
}

func TestListCompleted_EmptyBodyUsesDefaults(t *testing.T) {
	srv := newServer()
	req := httptest.NewRequest(http.MethodPost, "/list-completed", nil)
	req.Header.Set("Content-Type", "application/json")
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rr.Code)
	}
}

// ── ack / nack tests ──────────────────────────────────────────────────────────

func TestAck_RemovesFromQueue(t *testing.T) {
	ms := store.NewMemoryStore()
	srv := newServerWithStore(ms)

	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	post(srv, "/list-completed", map[string]any{"max": 1})

	rr := post(srv, "/ack", map[string]any{"handle": "h1"})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d", rr.Code)
	}
	if ms.QueueDepth() != 0 {
		t.Fatalf("expected empty queue after ack, got %d", ms.QueueDepth())
	}
	if ms.RegistrySize() != 0 {
		t.Fatalf("expected empty registry after ack, got %d", ms.RegistrySize())
	}
}

func TestNack_UnlocksItemForRedelivery(t *testing.T) {
	srv := newServer()

	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	// Lock it.
	post(srv, "/list-completed", map[string]any{"max": 1, "lock_ms": 60000})

	// Nack unlocks.
	rr := post(srv, "/nack", map[string]any{"handle": "h1"})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d", rr.Code)
	}

	// Should be available again.
	rr2 := post(srv, "/list-completed", map[string]any{"max": 1})
	var items []map[string]any
	if err := json.NewDecoder(rr2.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item after nack, got %d", len(items))
	}
}

// ── visibility timeout / reclaim tests ───────────────────────────────────────

func TestVisibilityTimeout_ReclaimExpiredReturnsItemToQueue(t *testing.T) {
	var tick int64 = 1000
	clock := func() int64 { return tick }
	ms := store.NewMemoryStoreWithClock(clock)
	srv := newServerWithStore(ms)

	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	// Lock with 2s window.
	post(srv, "/list-completed", map[string]any{"max": 1, "lock_ms": 2000})

	// Advance clock past lock expiry.
	tick = 4000

	// Reclaim expired locks.
	if err := ms.ReclaimExpired(nil); err != nil {
		t.Fatalf("reclaim: %v", err)
	}

	// Item should be available again.
	rr := post(srv, "/list-completed", map[string]any{"max": 1})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item after reclaim, got %d", len(items))
	}
}

// ── metadata propagation ──────────────────────────────────────────────────────

func TestListCompleted_IncludesMetadata(t *testing.T) {
	srv := newServer()
	meta := store.HandleMetadata{
		Kind:      "review-fix",
		Subkind:   "rebase",
		TaskID:    "T5",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	}
	mustRegister(t, srv, "h1", "n1", meta)
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	rr := post(srv, "/list-completed", map[string]any{"max": 1})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}
	m, ok := items[0]["metadata"].(map[string]any)
	if !ok {
		t.Fatalf("metadata missing or wrong type")
	}
	if m["kind"] != "review-fix" {
		t.Fatalf("expected kind=review-fix, got %v", m["kind"])
	}
	if m["subkind"] != "rebase" {
		t.Fatalf("expected subkind=rebase, got %v", m["subkind"])
	}
	if m["task_id"] != "T5" {
		t.Fatalf("expected task_id=T5, got %v", m["task_id"])
	}
}

